script:
$hermesDir = "C:\Users\E\AppData\Local\hermes"
"=== restoring config from backup ==="
$backup = Get-ChildItem "$hermesDir\backups" -Filter "config.yaml*" 2>$null | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if ($backup) {
  Copy-Item $backup.FullName "$hermesDir\config.yaml" -Force
  "Restored from: $($backup.Name)"
} else {
  "No backup found, checking installs..."
  Get-ChildItem "$hermesDir" -Filter "*.yaml" | Select-Object Name
}
